const SVGNS = "http://www.w3.org/2000/svg";
function cssvar(n){return getComputedStyle(document.documentElement).getPropertyValue(n).trim();}
function el(t,a){const e=document.createElementNS(SVGNS,t);for(const k in a)e.setAttribute(k,a[k]);return e;}
function mix(a,b,t){return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];}
function divColor(v,max){const t=Math.max(-1,Math.min(1,v/max));
  const warm=[198,39,45],cool=[38,110,142],mid=[236,232,222];
  const c=t>=0?mix(mid,warm,t):mix(mid,cool,-t);return `rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;}
function niceTicks(a,b,n){const s=(b-a)/n;const p=Math.pow(10,Math.floor(Math.log10(s)));
  const st=[1,2,2.5,5,10].map(x=>x*p).find(x=>x>=s)||p;
  const out=[];for(let t=Math.ceil(a/st)*st;t<=b;t+=st)out.push(+t.toFixed(6));return out;}
function fmt(v){return Math.abs(v)>=100?v.toFixed(0):v.toFixed(1);}

// ---- Warming stripes ----
function drawStripes(){
  const svg=document.getElementById('stripes');const box=svg.getBoundingClientRect();
  const W=box.width,H=box.height;if(W<40)return;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const d=DATA.stripes,n=d.length,bw=W/n;
  const amax=Math.max(...d.map(p=>Math.abs(p[1])))*1.02;
  d.forEach((p,i)=>{const r=el('rect',{x:i*bw,y:0,width:Math.ceil(bw)+0.5,height:H,fill:divColor(p[1],amax)});
    r.addEventListener('mousemove',()=>{document.getElementById('stripescap').textContent=
      `${p[0]}  \u00b7  ${p[1]>=0?'+':''}${p[1].toFixed(2)} \u00b0C respecto a 1971\u20132000`;});
    svg.appendChild(r);});
}

// ---- Gr\u00e1fica gen\u00e9rica (l\u00ednea/barra) con hover ----
function plotSeries(svgId,cfg,ttId){
  const svg=document.getElementById(svgId);
  const box=svg.parentElement.getBoundingClientRect();
  const W=box.width,H=Math.max(260,Math.min(400,W*0.52));if(W<40)return false;
  const m={l:50,r:14,t:12,b:28};
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const d=cfg.data,xs=d.map(p=>p[0]),ys=d.map(p=>p[1]);
  const xmin=Math.min(...xs),xmax=Math.max(...xs);
  let ymin=Math.min(...ys),ymax=Math.max(...ys);
  if(cfg.type==='bar'){ymin=Math.min(0,ymin);ymax=Math.max(0,ymax);}
  const pad=(ymax-ymin)*0.08||1;ymin-=pad;ymax+=pad;
  const SX=v=>m.l+(v-xmin)/(xmax-xmin)*(W-m.l-m.r);
  const SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  niceTicks(ymin,ymax,5).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-7,y:SY(t)+3,'text-anchor':'end'});tx.textContent=fmt(t);svg.appendChild(tx);});
  const step=Math.ceil((xmax-xmin)/8/10)*10||10;
  for(let y=Math.ceil(xmin/step)*step;y<=xmax;y+=step){
    const tx=el('text',{class:'axis',x:SX(y),y:H-8,'text-anchor':'middle'});tx.textContent=y;svg.appendChild(tx);}
  const amax=Math.max(...ys.map(Math.abs))*1.02||1;
  if(cfg.type==='bar'){const bw=Math.max(1,(W-m.l-m.r)/xs.length*0.82);const y0=SY(0);
    d.forEach(p=>{const col=cfg.diverging?divColor(p[1],amax):cssvar('--'+(cfg.color||'tide'));
      const yy=SY(p[1]);const est=cfg.estFrom&&p[0]>=cfg.estFrom;
      const r=el('rect',{x:SX(p[0])-bw/2,y:Math.min(y0,yy),width:bw,height:Math.abs(yy-y0),fill:col});
      if(est){r.setAttribute('opacity',0.45);r.setAttribute('stroke',cssvar('--ink'));
        r.setAttribute('stroke-dasharray','2 2');r.setAttribute('stroke-width',1);}
      svg.appendChild(r);});
    svg.appendChild(el('line',{class:'zeroline',x1:m.l,y1:y0,x2:W-m.r,y2:y0}));
  }else{let path='';d.forEach((p,i)=>path+=(i?'L':'M')+SX(p[0])+' '+SY(p[1]));
    svg.appendChild(el('path',{d:path,fill:'none',stroke:cssvar('--'+(cfg.color||'sea')),'stroke-width':2}));}
  const tr=cfg.trend;
  svg.appendChild(el('line',{class:'trend',x1:SX(tr.x0),y1:SY(tr.y0),x2:SX(tr.x1),y2:SY(tr.y1)}));
  const marker=el('circle',{class:'marker',r:4,opacity:0});svg.appendChild(marker);
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});
  const tt=document.getElementById(ttId);
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();
    const px=(ev.clientX-rb.left)/rb.width*W;
    const yr=Math.round(xmin+(px-m.l)/(W-m.l-m.r)*(xmax-xmin));
    const pt=d.reduce((a,b)=>Math.abs(b[0]-yr)<Math.abs(a[0]-yr)?b:a);
    marker.setAttribute('cx',SX(pt[0]));marker.setAttribute('cy',SY(pt[1]));marker.setAttribute('opacity',1);
    tt.style.left=(SX(pt[0])/W*rb.width)+'px';tt.style.top=(SY(pt[1])/H*rb.height)+'px';tt.style.opacity=1;
    const sign=pt[1]>=0&&cfg.diverging?'+':'';
    const est=cfg.estFrom&&pt[0]>=cfg.estFrom?' (est.)':'';
    tt.textContent=`${pt[0]}: ${sign}${pt[1].toFixed(cfg.unit.startsWith('mm')?0:2)} ${cfg.unit}${est}`;});
  ov.addEventListener('mouseleave',()=>{tt.style.opacity=0;marker.setAttribute('opacity',0);});
  svg.appendChild(ov);
  return true;
}
function capText(cfg){const tr=cfg.trend;
  return cfg.cap+'  \u00b7  tendencia '+(tr.dec>=0?'+':'')+tr.dec+' '+cfg.unit+'/d\u00e9cada'
    +(cfg.estNote?'  \u00b7  '+cfg.estNote:'');}

// ---- Explorador (Laredo) ----
let CUR=null;
function drawChart(cfg){CUR=cfg;
  if(!plotSeries('chart',cfg,'tt'))return;
  document.getElementById('vhead').textContent=cfg.head;
  document.getElementById('vheadlab').textContent=cfg.headlab;
  document.getElementById('vcap').textContent=capText(cfg);}
function buildTabs(){const box=document.getElementById('tabs');box.innerHTML='';
  DATA.vars.forEach((v,i)=>{const b=document.createElement('button');b.className='tab';
    b.textContent=v.label;b.setAttribute('aria-pressed',i===0);
    b.onclick=()=>{[...box.children].forEach(c=>c.setAttribute('aria-pressed',false));
      b.setAttribute('aria-pressed',true);drawChart(v);};box.appendChild(b);});}
function drawSiglo(){if(plotSeries('siglo',DATA.siglo,'ttsiglo'))
  document.getElementById('sigcap').textContent=capText(DATA.siglo);}
function drawSST(){if(plotSeries('sst',DATA.sst,'ttsst'))
  document.getElementById('sstcap').textContent=capText(DATA.sst);}

// ---- Calendario mes x a\u00f1o ----
function drawHeat(){
  const svg=document.getElementById('heat');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width,H=Math.max(220,Math.min(320,W*0.5));if(W<40)return;
  const m={l:24,r:8,t:6,b:20};const hm=DATA.heatmap,years=hm.years,ncol=years.length;
  const cw=(W-m.l-m.r)/ncol,ch=(H-m.t-m.b)/12;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  let amax=0;hm.grid.forEach(r=>r.forEach(v=>{if(v!=null)amax=Math.max(amax,Math.abs(v));}));
  const MES=['E','F','M','A','M','J','J','A','S','O','N','D'];
  for(let mo=0;mo<12;mo++){const ty=el('text',{class:'axis',x:m.l-5,y:m.t+ch*mo+ch/2+3,'text-anchor':'end'});
    ty.textContent=MES[mo];svg.appendChild(ty);
    const lab=el('rect',{x:0,y:m.t+ch*mo,width:m.l,height:ch,fill:'transparent'});lab.style.cursor='pointer';
    lab.addEventListener('click',()=>selectHeatMonth(mo));svg.appendChild(lab);
    for(let c=0;c<ncol;c++){const v=hm.grid[mo][c];if(v==null)continue;
      svg.appendChild(el('rect',{x:m.l+c*cw,y:m.t+mo*ch,width:Math.ceil(cw)+0.5,height:Math.ceil(ch)+0.5,fill:divColor(v,amax)}));}}
  for(let i=0;i<ncol;i++){if(years[i]%10===0){const tx=el('text',{class:'axis',x:m.l+i*cw+cw/2,y:H-6,'text-anchor':'middle'});
    tx.textContent=years[i];svg.appendChild(tx);}}
  const tt=document.getElementById('tth');
  const MESL=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});ov.style.cursor='pointer';
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();
    const px=(ev.clientX-rb.left)/rb.width*W,py=(ev.clientY-rb.top)/rb.height*H;
    const c=Math.floor((px-m.l)/cw),mo=Math.floor((py-m.t)/ch);
    if(c<0||c>=ncol||mo<0||mo>11){tt.style.opacity=0;return;}
    const v=hm.grid[mo][c];if(v==null){tt.style.opacity=0;return;}
    tt.style.left=((m.l+c*cw+cw/2)/W*rb.width)+'px';tt.style.top=((m.t+mo*ch)/H*rb.height)+'px';tt.style.opacity=1;
    tt.textContent=`${MESL[mo]} ${years[c]}: ${v>=0?'+':''}${v.toFixed(2)} \u00b0C`;});
  ov.addEventListener('mouseleave',()=>tt.style.opacity=0);
  ov.addEventListener('click',ev=>{const rb=svg.getBoundingClientRect();
    const px=(ev.clientX-rb.left)/rb.width*W;const c=Math.floor((px-m.l)/cw);
    if(c>=0&&c<ncol)selectHeatYear(c);});
  svg.appendChild(ov);
}

// ---- Gr\u00e1fica acompa\u00f1ante del calendario (mes o a\u00f1o) ----
const MESLARGO=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
let heatSel=null;
function jsTrend(data){const n=data.length,mx=data.reduce((a,p)=>a+p[0],0)/n,my=data.reduce((a,p)=>a+p[1],0)/n;
  let num=0,den=0;data.forEach(p=>{num+=(p[0]-mx)*(p[1]-my);den+=(p[0]-mx)**2;});const s=num/den,b=my-s*mx;
  const x0=data[0][0],x1=data[data.length-1][0];
  return {x0,y0:+(s*x0+b).toFixed(3),x1,y1:+(s*x1+b).toFixed(3),dec:+(s*10).toFixed(3)};}
function quantile(sorted,q){if(!sorted.length)return 0;const pos=(sorted.length-1)*q,b=Math.floor(pos),r=pos-b;
  return sorted[b+1]!==undefined?sorted[b]+r*(sorted[b+1]-sorted[b]):sorted[b];}
function heatAxes(svg,W,H,m,xmin,xmax,ymin,ymax,xlabels){
  const SX=v=>m.l+(v-xmin)/(xmax-xmin)*(W-m.l-m.r),SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  niceTicks(ymin,ymax,4).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-6,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t.toFixed(1);svg.appendChild(tx);});
  xlabels.forEach(a=>{const tx=el('text',{class:'axis',x:SX(a[0]),y:H-7,'text-anchor':'middle'});tx.textContent=a[1];svg.appendChild(tx);});
  svg.appendChild(el('line',{class:'zeroline',x1:m.l,y1:SY(0),x2:W-m.r,y2:SY(0)}));
  return {SX,SY};}
function drawHeatMonth(mo){
  const hm=DATA.heatmap,years=hm.years;const svg=document.getElementById('heatline');
  const box=svg.parentElement.getBoundingClientRect();const W=box.width;if(W<40)return;
  const H=Math.max(220,Math.min(300,W*0.32)),m={l:38,r:12,t:10,b:22};
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  let ymin=1e9,ymax=-1e9;hm.grid.forEach(r=>r.forEach(v=>{if(v!=null){ymin=Math.min(ymin,v);ymax=Math.max(ymax,v);}}));
  const pad=(ymax-ymin)*0.05;ymin-=pad;ymax+=pad;
  const xlabels=[];for(let y=Math.ceil(years[0]/20)*20;y<=years[years.length-1];y+=20)xlabels.push([y,y]);
  const {SX,SY}=heatAxes(svg,W,H,m,years[0],years[years.length-1],ymin,ymax,xlabels);
  for(let mm=0;mm<12;mm++){if(mm===mo)continue;let p='',st=false;
    years.forEach((y,i)=>{const v=hm.grid[mm][i];if(v!=null){p+=(st?'L':'M')+SX(y)+' '+SY(v);st=true;}});
    if(p)svg.appendChild(el('path',{d:p,fill:'none',stroke:cssvar('--grid'),'stroke-width':1}));}
  const data=years.map((y,i)=>[y,hm.grid[mo][i]]).filter(p=>p[1]!=null);const tr=jsTrend(data);
  svg.appendChild(el('line',{class:'trend',x1:SX(tr.x0),y1:SY(tr.y0),x2:SX(tr.x1),y2:SY(tr.y1),opacity:0.6}));
  let p='';data.forEach((pt,i)=>p+=(i?'L':'M')+SX(pt[0])+' '+SY(pt[1]));
  svg.appendChild(el('path',{d:p,fill:'none',stroke:cssvar('--warm'),'stroke-width':2.6}));
  const tt=document.getElementById('ttl');const mk=el('circle',{r:4,fill:cssvar('--warm'),opacity:0});svg.appendChild(mk);
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();const px=(ev.clientX-rb.left)/rb.width*W;
    const yr=Math.round(years[0]+(px-m.l)/(W-m.l-m.r)*(years[years.length-1]-years[0]));
    const pt=data.reduce((a,b)=>Math.abs(b[0]-yr)<Math.abs(a[0]-yr)?b:a);
    mk.setAttribute('cx',SX(pt[0]));mk.setAttribute('cy',SY(pt[1]));mk.setAttribute('opacity',1);
    tt.style.left=(SX(pt[0])/W*rb.width)+'px';tt.style.top=(SY(pt[1])/H*rb.height)+'px';tt.style.opacity=1;
    tt.textContent=`${MESLARGO[mo]} ${pt[0]}: ${pt[1]>=0?'+':''}${pt[1].toFixed(2)} \u00b0C`;});
  ov.addEventListener('mouseleave',()=>{tt.style.opacity=0;mk.setAttribute('opacity',0);});svg.appendChild(ov);
  document.getElementById('heltitle').textContent=`${MESLARGO[mo][0].toUpperCase()+MESLARGO[mo].slice(1)} a lo largo de los a\u00f1os  \u00b7  en gris, los otros meses`;
  document.getElementById('helcap').textContent=`Anomal\u00eda de ${MESLARGO[mo]} vs 1961\u201390 \u00b7 tendencia ${tr.dec>=0?'+':''}${tr.dec} \u00b0C/d\u00e9cada`;}
function drawHeatYear(col){
  const hm=DATA.heatmap,years=hm.years,yr=years[col];const svg=document.getElementById('heatline');
  const box=svg.parentElement.getBoundingClientRect();const W=box.width;if(W<40)return;
  const H=Math.max(220,Math.min(300,W*0.32)),m={l:38,r:12,t:10,b:22};
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const lo=[],hi=[],med=[],cur=[];
  for(let mo=0;mo<12;mo++){const arr=hm.grid[mo].filter(v=>v!=null).slice().sort((a,b)=>a-b);
    lo.push(quantile(arr,0.1));hi.push(quantile(arr,0.9));med.push(quantile(arr,0.5));cur.push(hm.grid[mo][col]);}
  const cv=cur.filter(v=>v!=null);
  let ymin=Math.min(...lo,...cv),ymax=Math.max(...hi,...cv);const pad=(ymax-ymin)*0.08;ymin-=pad;ymax+=pad;
  const MES=['E','F','M','A','M','J','J','A','S','O','N','D'];
  const {SX,SY}=heatAxes(svg,W,H,m,0,11,ymin,ymax,MES.map((s,i)=>[i,s]));
  let area='';for(let mo=0;mo<12;mo++)area+=(mo?'L':'M')+SX(mo)+' '+SY(hi[mo]);
  for(let mo=11;mo>=0;mo--)area+='L'+SX(mo)+' '+SY(lo[mo]);area+='Z';
  svg.appendChild(el('path',{d:area,fill:cssvar('--tide'),opacity:0.13}));
  let pm='';med.forEach((v,mo)=>pm+=(mo?'L':'M')+SX(mo)+' '+SY(v));
  svg.appendChild(el('path',{d:pm,fill:'none',stroke:cssvar('--muted'),'stroke-width':1.2,'stroke-dasharray':'3 3'}));
  const dsel=[];for(let mo=0;mo<12;mo++)if(cur[mo]!=null)dsel.push([mo,cur[mo]]);
  let p='';dsel.forEach((pt,i)=>p+=(i?'L':'M')+SX(pt[0])+' '+SY(pt[1]));
  svg.appendChild(el('path',{d:p,fill:'none',stroke:cssvar('--warm'),'stroke-width':2.6}));
  dsel.forEach(pt=>svg.appendChild(el('circle',{cx:SX(pt[0]),cy:SY(pt[1]),r:3,fill:cssvar('--warm')})));
  const tt=document.getElementById('ttl');
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();const px=(ev.clientX-rb.left)/rb.width*W;
    const mo=Math.max(0,Math.min(11,Math.round((px-m.l)/((W-m.l-m.r)/11))));const v=cur[mo];if(v==null){tt.style.opacity=0;return;}
    tt.style.left=(SX(mo)/W*rb.width)+'px';tt.style.top=(SY(v)/H*rb.height)+'px';tt.style.opacity=1;
    tt.textContent=`${MESLARGO[mo]} ${yr}: ${v>=0?'+':''}${v.toFixed(2)} \u00b0C`;});
  ov.addEventListener('mouseleave',()=>tt.style.opacity=0);svg.appendChild(ov);
  const media=cv.reduce((a,b)=>a+b,0)/cv.length;
  document.getElementById('heltitle').textContent=`Los 12 meses de ${yr}  \u00b7  banda = rango normal (P10\u2013P90, 1981\u2013hoy)`;
  document.getElementById('helcap').textContent=`Anomal\u00eda mensual de ${yr} vs 1961\u201390 \u00b7 media del a\u00f1o ${media>=0?'+':''}${media.toFixed(2)} \u00b0C`;}
function selectHeatMonth(mo){heatSel={t:'month',i:mo};drawHeatMonth(mo);}
function selectHeatYear(col){heatSel={t:'year',i:col};drawHeatYear(col);}
function drawHeatSel(){if(!heatSel)heatSel={t:'year',i:DATA.heatmap.years.length-1};
  heatSel.t==='month'?drawHeatMonth(heatSel.i):drawHeatYear(heatSel.i);}

// ---- Distribuci\u00f3n por d\u00e9cada (animada) ----
let distSel=0,distTimer=null;
function drawDist(){
  const svg=document.getElementById('dist');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width,H=Math.max(220,Math.min(320,W*0.5));if(W<40)return;
  const m={l:16,r:12,t:8,b:24};const ds=DATA.dist,bins=ds.bins,decs=ds.decades;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const xmin=bins[0],xmax=bins[bins.length-1]+1;
  let ymax=0;decs.forEach(d=>d.h.forEach(v=>ymax=Math.max(ymax,v)));ymax*=1.1;
  const SX=v=>m.l+(v-xmin)/(xmax-xmin)*(W-m.l-m.r),SY=v=>H-m.b-(v/ymax)*(H-m.t-m.b);
  for(let t=0;t<=30;t+=5){const tx=el('text',{class:'axis',x:SX(t),y:H-8,'text-anchor':'middle'});tx.textContent=t+'\u00b0';svg.appendChild(tx);}
  const pf=d=>{let p='';bins.forEach((b,i)=>p+=(i?'L':'M')+SX(b+0.5)+' '+SY(d.h[i]));return p;};
  decs.forEach((d,i)=>{if(i===distSel)return;svg.appendChild(el('path',{d:pf(d),fill:'none',stroke:cssvar('--line'),'stroke-width':1.1}));});
  const cur=decs[distSel];let area=`M ${SX(bins[0]+0.5)} ${SY(0)}`;
  bins.forEach((b,i)=>area+=' L '+SX(b+0.5)+' '+SY(cur.h[i]));area+=` L ${SX(bins[bins.length-1]+0.5)} ${SY(0)} Z`;
  svg.appendChild(el('path',{d:area,fill:cssvar('--tide'),opacity:0.18}));
  svg.appendChild(el('path',{d:pf(cur),fill:'none',stroke:cssvar('--tide'),'stroke-width':2.5}));
  svg.appendChild(el('line',{x1:SX(cur.mean),y1:m.t,x2:SX(cur.mean),y2:H-m.b,stroke:cssvar('--warm'),'stroke-width':1.5,'stroke-dasharray':'4 3'}));
  document.getElementById('dhead').textContent=cur.label+'  ('+cur.mean.toFixed(1)+' \u00b0C)';
}
function buildDistTabs(){const box=document.getElementById('disttabs');box.innerHTML='';
  DATA.dist.decades.forEach((d,i)=>{const b=document.createElement('button');b.className='tab';
    b.textContent=d.label;b.setAttribute('aria-pressed',i===distSel);
    b.onclick=()=>{stopPlay();distSel=i;drawDist();syncDistTabs();};box.appendChild(b);});}
function syncDistTabs(){[...document.getElementById('disttabs').children].forEach((c,i)=>c.setAttribute('aria-pressed',i===distSel));}
function stopPlay(){if(distTimer){clearInterval(distTimer);distTimer=null;document.getElementById('playbtn').textContent='\u25b6 Reproducir evoluci\u00f3n';}}
function playDist(){const btn=document.getElementById('playbtn');if(distTimer){stopPlay();return;}
  btn.textContent='\u23f8 Pausar';distTimer=setInterval(()=>{distSel=(distSel+1)%DATA.dist.decades.length;drawDist();syncDistTabs();},950);}

// ---- Animaci\u00f3n nivel del mar ----
let seaK=null,seaTimer=null;
function drawSeaAnim(){
  const svg=document.getElementById('seaanim');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const H=Math.max(240,Math.min(380,W*0.42));
  const m={l:46,r:14,t:12,b:26};const d=DATA.mar.data;if(seaK===null)seaK=d.length-1;
  const xs=d.map(p=>p[0]),ys=d.map(p=>p[1]);
  const xmin=Math.min(...xs),xmax=Math.max(...xs);
  let ymin=Math.min(...ys),ymax=Math.max(...ys);const pad=(ymax-ymin)*0.08;ymin-=pad;ymax+=pad;
  const SX=v=>m.l+(v-xmin)/(xmax-xmin)*(W-m.l-m.r),SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  niceTicks(ymin,ymax,5).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-6,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t;svg.appendChild(tx);});
  for(let y=1950;y<=xmax;y+=20){const tx=el('text',{class:'axis',x:SX(y),y:H-8,'text-anchor':'middle'});tx.textContent=y;svg.appendChild(tx);}
  let full='';d.forEach((p,i)=>full+=(i?'L':'M')+SX(p[0])+' '+SY(p[1]));
  svg.appendChild(el('path',{d:full,fill:'none',stroke:cssvar('--line'),'stroke-width':1.2}));
  const sub=d.slice(0,seaK+1);let area=`M ${SX(sub[0][0])} ${SY(ymin)}`;
  sub.forEach(p=>area+=' L '+SX(p[0])+' '+SY(p[1]));area+=` L ${SX(sub[sub.length-1][0])} ${SY(ymin)} Z`;
  svg.appendChild(el('path',{d:area,fill:cssvar('--sea'),opacity:0.16}));
  let ln='';sub.forEach((p,i)=>ln+=(i?'L':'M')+SX(p[0])+' '+SY(p[1]));
  svg.appendChild(el('path',{d:ln,fill:'none',stroke:cssvar('--sea'),'stroke-width':2.5}));
  const last=sub[sub.length-1];
  svg.appendChild(el('circle',{cx:SX(last[0]),cy:SY(last[1]),r:5,fill:cssvar('--sea'),stroke:'#fff','stroke-width':1.5}));
  document.getElementById('seahead').textContent=last[0];
  document.getElementById('sealab').textContent=`${last[1]>=0?'+':''}${(last[1]/10).toFixed(1)} cm sobre el nivel de 1944\u20131963`;
}
function playSea(){const btn=document.getElementById('seaplay');const d=DATA.mar.data;
  if(seaTimer){clearInterval(seaTimer);seaTimer=null;btn.textContent='\u25b6 Ver subir el mar';return;}
  seaK=0;btn.textContent='\u23f8 Pausar';
  seaTimer=setInterval(()=>{seaK++;if(seaK>=d.length){seaK=d.length-1;clearInterval(seaTimer);seaTimer=null;btn.textContent='\u25b6 Ver de nuevo';}drawSeaAnim();},70);}

// ---- Mapa (tendencia + a\u00f1o a a\u00f1o, en el mismo SVG) ----
function pnpoly(x,y,ring){let inside=false;
  for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];
    if(((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))inside=!inside;}return inside;}
function seqColor(v,a,b){const t=Math.max(0,Math.min(1,(v-a)/(b-a||1)));
  const c=mix([255,241,204],[176,24,43],t);return `rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;}
function proj(ring,W){
  let lon0=Math.min(...ring.map(p=>p[0])),lon1=Math.max(...ring.map(p=>p[0]));
  let lat0=Math.min(...ring.map(p=>p[1])),lat1=Math.max(...ring.map(p=>p[1]));
  const pad=0.04;lon0-=pad;lon1+=pad;lat0-=pad;lat1+=pad;
  const coslat=Math.cos((lat0+lat1)/2*Math.PI/180);
  const H=Math.max(230,W*(lat1-lat0)/((lon1-lon0)*coslat));const mg=6;
  return {H,lon0,lon1,lat0,lat1,mg,SX:lo=>mg+(lo-lon0)/(lon1-lon0)*(W-2*mg),SY:la=>mg+(lat1-la)/(lat1-lat0)*(H-2*mg)};}
function outlinePath(ring,P){let path='';ring.forEach((p,i)=>path+=(i?'L':'M')+P.SX(p[0]).toFixed(1)+' '+P.SY(p[1]).toFixed(1));return path+'Z';}
function mapClip(svg,P,ring){
  const defs=el('defs',{});const cp=el('clipPath',{id:'capclip'});
  cp.appendChild(el('path',{d:outlinePath(ring,P)}));defs.appendChild(cp);svg.appendChild(defs);
  const g=el('g',{'clip-path':'url(#capclip)'});svg.appendChild(g);return g;}
function mapFrame(svg,P,W,ring){
  svg.appendChild(el('path',{d:outlinePath(ring,P),fill:'none',stroke:cssvar('--ink'),'stroke-width':1.3,opacity:0.6}));
  const placed=[];
  DATA.map.towns.forEach(t=>{const x=P.SX(t[2]),y=P.SY(t[1]);
    svg.appendChild(el('circle',{cx:x,cy:y,r:2.8,fill:cssvar('--ink'),stroke:'#fff','stroke-width':0.9}));
    if(placed.some(q=>Math.abs(q[0]-x)<44&&Math.abs(q[1]-y)<11))return;  // evita etiquetas solapadas
    const tx=el('text',{class:'axis',x:x+4,y:y+3,fill:cssvar('--ink')});tx.textContent=t[0];svg.appendChild(tx);
    placed.push([x,y]);});}
function mapHover(svg,P,W,H,ring,valueAt){
  const tt=document.getElementById('ttm');
  const ov=el('rect',{x:0,y:0,width:W,height:H,fill:'transparent'});ov.style.cursor='pointer';
  const toLL=ev=>{const rb=svg.getBoundingClientRect();
    const px=(ev.clientX-rb.left)/rb.width*W,py=(ev.clientY-rb.top)/rb.height*H;
    return [P.lon0+(px-P.mg)/(W-2*P.mg)*(P.lon1-P.lon0),P.lat1-(py-P.mg)/(H-2*P.mg)*(P.lat1-P.lat0),px,py,rb];};
  ov.addEventListener('mousemove',ev=>{const[lo,la,px,py,rb]=toLL(ev);
    if(!pnpoly(lo,la,ring)){tt.style.opacity=0;return;}
    const val=valueAt(la,lo);if(val==null){tt.style.opacity=0;return;}
    tt.style.left=(px/W*rb.width)+'px';tt.style.top=(py/H*rb.height)+'px';tt.style.opacity=1;tt.textContent=val;});
  ov.addEventListener('mouseleave',()=>tt.style.opacity=0);
  ov.addEventListener('click',ev=>{const[lo,la]=toLL(ev);
    let best=null,bd=9e9;DATA.map.towns.forEach(t=>{const d=Math.abs(t[1]-la)+Math.abs(t[2]-lo);if(d<bd){bd=d;best=t;}});
    if(best&&bd<0.16)selectTown(best[0]);});
  svg.appendChild(ov);}

function drawMapTrend(){
  const svg=document.getElementById('map');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const mp=DATA.map;if(!mp.cells)return;const ring=mp.outline[0];
  const P=proj(ring,W),H=P.H,step=mp.step;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const tmin=Math.min(...mp.cells.map(c=>c[2])),tmax=Math.max(...mp.cells.map(c=>c[2]));
  const g=mapClip(svg,P,ring);
  mp.cells.forEach(c=>{const la=c[0],lo=c[1],t=c[2];
    const x=P.SX(lo-step/2),y=P.SY(la+step/2),w=P.SX(lo+step/2)-P.SX(lo-step/2),h=P.SY(la-step/2)-P.SY(la+step/2);
    g.appendChild(el('rect',{x:x,y:y,width:w+0.6,height:h+0.6,fill:seqColor(t,tmin,tmax)}));});
  mapFrame(svg,P,W,ring);
  mapHover(svg,P,W,H,ring,(la,lo)=>{let best=null,bd=9e9;mp.cells.forEach(c=>{const d=Math.abs(c[0]-la)+Math.abs(c[1]-lo);if(d<bd){bd=d;best=c;}});
    return best?`+${(best[2]*DATA.span/10).toFixed(1)} \u00b0C desde ${DATA.y0} (+${best[2].toFixed(2)}/d\u00e9c)`:null;});
}
let myIdx=null,myTimer=null,myMeans=null;
function cellMean(vals,years){let s=0,n=0;years.forEach((y,i)=>{if(y>=1981&&y<=2010&&vals[i]!=null){s+=vals[i];n++;}});return n?s/n:null;}
function drawMapYear(){
  const gy=DATA.gridyears;if(!gy)return;
  const svg=document.getElementById('map');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const ring=DATA.map.outline[0];
  if(myIdx===null)myIdx=gy.years.length-1;
  if(!myMeans)myMeans=gy.cells.map(c=>cellMean(c[2],gy.years));
  const P=proj(ring,W),H=P.H,step=gy.step;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const g=mapClip(svg,P,ring);
  gy.cells.forEach((c,ci)=>{const la=c[0],lo=c[1];
    const v=c[2][myIdx],mn=myMeans[ci];if(v==null||mn==null)return;
    const x=P.SX(lo-step/2),y=P.SY(la+step/2),w=P.SX(lo+step/2)-P.SX(lo-step/2),h=P.SY(la-step/2)-P.SY(la+step/2);
    g.appendChild(el('rect',{x:x,y:y,width:w+0.6,height:h+0.6,fill:divColor(v-mn,2.0)}));});
  mapFrame(svg,P,W,ring);
  mapHover(svg,P,W,H,ring,(la,lo)=>{let bi=0,bd=9e9;gy.cells.forEach((c,i)=>{const d=Math.abs(c[0]-la)+Math.abs(c[1]-lo);if(d<bd){bd=d;bi=i;}});
    const v=gy.cells[bi][2][myIdx],mn=myMeans[bi];return v==null?null:`${gy.years[myIdx]}: ${(v-mn>=0?'+':'')}${(v-mn).toFixed(2)} \u00b0C`;});
  document.getElementById('myhead').textContent=gy.years[myIdx];
  document.getElementById('myslider').value=myIdx;
}
let mapMode='year';
function drawMapActive(){mapMode==='trend'?drawMapTrend():drawMapYear();}
function setMapMode(mode){mapMode=mode;
  document.getElementById('mmYear').setAttribute('aria-pressed',mode==='year');
  document.getElementById('mmTrend').setAttribute('aria-pressed',mode==='trend');
  document.getElementById('maphead').style.display=mode==='year'?'flex':'none';
  document.getElementById('mapctl').style.display=mode==='year'?'flex':'none';
  document.getElementById('mapcap').textContent=mode==='year'
    ?'Anomal\u00eda anual vs 1981\u20132010 \u00b7 NASA POWER \u00b7 desliza o dale al play'
    :'Calentamiento total desde 1981 (y por d\u00e9cada) \u00b7 NASA POWER 1981\u20132025 \u00b7 pincha un pueblo';
  if(mapMode==='trend'&&myTimer){clearInterval(myTimer);myTimer=null;document.getElementById('myplay').textContent='\u25b6 Reproducir';}
  drawMapActive();}
function playMapYear(){const btn=document.getElementById('myplay');const gy=DATA.gridyears;
  if(myTimer){clearInterval(myTimer);myTimer=null;btn.textContent='\u25b6 Reproducir';return;}
  myIdx=0;btn.textContent='\u23f8 Pausar';
  myTimer=setInterval(()=>{myIdx++;if(myIdx>=gy.years.length){myIdx=gy.years.length-1;clearInterval(myTimer);myTimer=null;btn.textContent='\u25b6 Reproducir';}drawMapYear();},280);}

// ---- Comparador ----
let cmpA=0,cmpB=0;
function townCellIdx(ti){const t=DATA.map.towns[ti],la=t[1],lo=t[2],gy=DATA.gridyears;
  let bi=0,bd=9e9;gy.cells.forEach((c,i)=>{const d=Math.abs(c[0]-la)+Math.abs(c[1]-lo);if(d<bd){bd=d;bi=i;}});return bi;}
function townAnom(ti){const gy=DATA.gridyears,ci=townCellIdx(ti),vals=gy.cells[ci][2];
  const mn=(myMeans?myMeans[ci]:cellMean(vals,gy.years));
  return gy.years.map((y,i)=>vals[i]==null?null:[y,+(vals[i]-mn).toFixed(2)]).filter(Boolean);}
function slope10(s){const n=s.length,mx=s.reduce((a,p)=>a+p[0],0)/n,my=s.reduce((a,p)=>a+p[1],0)/n;
  let num=0,den=0;s.forEach(p=>{num+=(p[0]-mx)*(p[1]-my);den+=(p[0]-mx)**2;});return num/den*10;}
function drawCmp(){
  const gy=DATA.gridyears;if(!gy)return;
  const svg=document.getElementById('cmp');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const H=Math.max(240,Math.min(360,W*0.6));
  const m={l:40,r:12,t:10,b:24};const A=townAnom(cmpA),B=townAnom(cmpB),all=A.concat(B);
  const xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);
  const xmin=Math.min(...xs),xmax=Math.max(...xs);let ymin=Math.min(...ys),ymax=Math.max(...ys);
  const pad=(ymax-ymin)*0.1||0.5;ymin-=pad;ymax+=pad;
  const SX=v=>m.l+(v-xmin)/(xmax-xmin)*(W-m.l-m.r),SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  niceTicks(ymin,ymax,5).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-6,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t.toFixed(1);svg.appendChild(tx);});
  for(let y=1985;y<=xmax;y+=10){const tx=el('text',{class:'axis',x:SX(y),y:H-8,'text-anchor':'middle'});tx.textContent=y;svg.appendChild(tx);}
  svg.appendChild(el('line',{class:'zeroline',x1:m.l,y1:SY(0),x2:W-m.r,y2:SY(0)}));
  const line=(s,col)=>{let p='';s.forEach((pt,i)=>p+=(i?'L':'M')+SX(pt[0])+' '+SY(pt[1]));svg.appendChild(el('path',{d:p,fill:'none',stroke:col,'stroke-width':2.2}));};
  line(A,cssvar('--warm'));line(B,cssvar('--tide'));
  const nA=DATA.map.towns[cmpA][0],nB=DATA.map.towns[cmpB][0],sA=slope10(A),sB=slope10(B);
  const tA=sA*DATA.span/10,tB=sB*DATA.span/10;
  document.getElementById('cmpcap').textContent=
    `${nA}: +${tA.toFixed(1)} \u00b0C desde ${DATA.y0} (${sA>=0?'+':''}${sA.toFixed(2)}/d\u00e9c)   \u00b7   ${nB}: +${tB.toFixed(1)} \u00b0C (${sB>=0?'+':''}${sB.toFixed(2)}/d\u00e9c)`;
}
function buildCmpTabs(){const towns=DATA.map.towns;
  const mk=(id,getV,setV)=>{const box=document.getElementById(id);box.innerHTML='';
    towns.forEach((t,i)=>{const b=document.createElement('button');b.className='tab';b.textContent=t[0];
      b.setAttribute('aria-pressed',i===getV());
      b.onclick=()=>{setV(i);[...box.children].forEach((c,j)=>c.setAttribute('aria-pressed',j===i));drawCmp();};box.appendChild(b);});};
  mk('cmpA',()=>cmpA,v=>cmpA=v);mk('cmpB',()=>cmpB,v=>cmpB=v);}

// ---- Ranking (calentamiento TOTAL desde 1981; clicable) ----
function buildRanking(){const box=document.getElementById('ranking');box.innerHTML='';
  const max=Math.max(...DATA.pueblos.map(p=>p[2]));
  DATA.pueblos.slice().reverse().forEach(([name,dec,tot])=>{const lar=name==='Laredo';
    const row=document.createElement('div');row.className='rk'+(lar?' lar':'');row.dataset.town=name;
    row.innerHTML=`<div class="name">${name}</div><div class="barwrap"><div class="bar${lar?' lar':''}" style="width:${tot/max*100}%"></div></div><div class="val">+${tot.toFixed(1)}\u00b0</div>`;
    row.title=`${name}: +${tot.toFixed(1)} \u00b0C desde ${DATA.y0} (${dec>=0?'+':''}${dec.toFixed(2)} \u00b0C/d\u00e9cada)`;
    row.onclick=()=>selectTown(name);
    box.appendChild(row);});}
function selectTown(name){const i=DATA.map.towns.findIndex(t=>t[0]===name);if(i<0)return;
  cmpA=i;const box=document.getElementById('cmpA');
  if(box)[...box.children].forEach((c,j)=>c.setAttribute('aria-pressed',j===i));
  drawCmp();
  document.querySelectorAll('#ranking .rk').forEach(r=>r.classList.toggle('sel',r.dataset.town===name));}

// ---- Render + navegaci\u00f3n ----
// ---- Bilbao (2\u00aa referencia real) ----
function drawBilbao(){if(DATA.bilbao&&plotSeries('bilbao',DATA.bilbao,'ttbilbao'))
  document.getElementById('bilcap').textContent=capText(DATA.bilbao);}

// ---- Estaci\u00f3n RUBAYA (tiempo real) ----
const SEASONCOL={Invierno:'#2980b9',Primavera:'#27ae60',Verano:'#c0392b',['Oto'+String.fromCharCode(241)+'o']:'#e67e22'};
function drawEstMeta(){if(!DATA.est)return;const m=DATA.est.meta;
  document.getElementById('estmeta').innerHTML=`En Laredo (${m.lat} N, ${Math.abs(m.lon)} O), ~6 m. Cada hora desde <b>${m.desde}</b> \u00b7 ${m.ndias} d\u00edas con dato (hueco en 2022).`;
  document.getElementById('estnow').innerHTML=`\u00daltima lectura (${m.ultima_fecha}): m\u00e1x <b>${m.ultima_tmax} \u00b0C</b> / m\u00edn <b>${m.ultima_tmin} \u00b0C</b>. <span style="opacity:.7">Estaci\u00f3n de aficionado: patrones fiables, extremos con cautela.</span>`;}
function drawDiaTipico(){if(!DATA.est)return;const svg=document.getElementById('diatipico');
  const box=svg.parentElement.getBoundingClientRect();const W=box.width;if(W<40)return;const H=Math.max(220,Math.min(300,W*0.62));
  const m={l:32,r:10,t:22,b:22};const dt=DATA.est.diatipico;
  let ymin=1e9,ymax=-1e9;Object.values(dt).forEach(a=>a.forEach(v=>{if(v!=null){ymin=Math.min(ymin,v);ymax=Math.max(ymax,v);}}));
  const pad=(ymax-ymin)*0.08;ymin-=pad;ymax+=pad;
  const SX=h=>m.l+h/23*(W-m.l-m.r),SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  niceTicks(ymin,ymax,4).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-5,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t.toFixed(0);svg.appendChild(tx);});
  for(let h=0;h<=23;h+=6){const tx=el('text',{class:'axis',x:SX(h),y:H-7,'text-anchor':'middle'});tx.textContent=h+'h';svg.appendChild(tx);}
  let lx=m.l;Object.keys(dt).forEach(est=>{const t=el('text',{x:lx,y:12,'font-size':'9.5','font-family':'ui-monospace',fill:SEASONCOL[est]});t.textContent=est;svg.appendChild(t);lx+=(W-m.l-m.r)/4;});
  Object.keys(dt).forEach(est=>{const a=dt[est];let p='',st=false;
    a.forEach((v,h)=>{if(v!=null){p+=(st?'L':'M')+SX(h)+' '+SY(v);st=true;}});
    if(p)svg.appendChild(el('path',{d:p,fill:'none',stroke:SEASONCOL[est],'stroke-width':2.2}));});
  const tt=document.getElementById('ttdt');const V='Verano',I='Invierno';
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();const px=(ev.clientX-rb.left)/rb.width*W;
    const h=Math.max(0,Math.min(23,Math.round((px-m.l)/((W-m.l-m.r)/23))));
    tt.style.left=(SX(h)/W*rb.width)+'px';tt.style.top='18px';tt.style.opacity=1;
    tt.textContent=`${h}h \u00b7 verano ${dt[V][h]}\u00b0 \u00b7 invierno ${dt[I][h]}\u00b0`;});
  ov.addEventListener('mouseleave',()=>tt.style.opacity=0);svg.appendChild(ov);}
function warmScale(t,a,b){const x=Math.max(0,Math.min(1,(t-a)/(b-a||1)));const c=mix([255,241,204],[176,24,43],x);return `rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;}
function barsCat(svgId,ttId,items,valFn,labFn,colFn,tipFn){
  const svg=document.getElementById(svgId);const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const H=Math.max(200,Math.min(280,W*0.62));const m={l:28,r:10,t:10,b:22};
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  const vals=items.map(valFn);let ymax=Math.max(...vals)*1.18||1;
  const SY=v=>H-m.b-v/ymax*(H-m.t-m.b);
  niceTicks(0,ymax,4).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-5,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t.toFixed(0);svg.appendChild(tx);});
  const n=items.length,bw=(W-m.l-m.r)/n*0.62;const tt=document.getElementById(ttId);
  items.forEach((it,i)=>{const cx=m.l+(i+0.5)*(W-m.l-m.r)/n,v=valFn(it),y=SY(v),y0=SY(0);
    const r=el('rect',{x:cx-bw/2,y:y,width:bw,height:y0-y,fill:colFn(it)});
    r.addEventListener('mousemove',()=>{const rb=svg.getBoundingClientRect();tt.style.left=(cx/W*rb.width)+'px';tt.style.top=(y/H*rb.height)+'px';tt.style.opacity=1;tt.textContent=tipFn(it);});
    r.addEventListener('mouseleave',()=>tt.style.opacity=0);svg.appendChild(r);
    const tx=el('text',{class:'axis',x:cx,y:H-7,'text-anchor':'middle'});tx.textContent=labFn(it);svg.appendChild(tx);});}
function drawVeranos(){if(!DATA.est)return;const vs=DATA.est.veranos;
  const mn=Math.min(...vs.map(v=>v.media)),mx=Math.max(...vs.map(v=>v.media));
  barsCat('veranos','ttv',vs,v=>v.media,v=>v.anio+(v.anio===DATA.est.verano_anio?'*':''),
    v=>warmScale(v.media,mn-0.5,mx+0.5),
    v=>`${v.anio}: media ${v.media}\u00b0 \u00b7 ${v.hot30} d\u00edas \u226530\u00b0 \u00b7 ${v.ntrop} noches trop. \u00b7 pico ${v.pico}\u00b0`);}
function drawNtrop(){if(!DATA.est)return;const vs=DATA.est.veranos;const mx=Math.max(...vs.map(v=>v.ntrop));
  barsCat('ntrop','ttn',vs,v=>v.ntrop,v=>v.anio+(v.anio===DATA.est.verano_anio?'*':''),
    v=>v.anio===DATA.est.verano_anio?cssvar('--warm'):warmScale(v.ntrop,0,mx),
    v=>`${v.anio}: ${v.ntrop} noches tropicales`);}
const MESAB=['','ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
function drawVeranoHora(){if(!DATA.est||!DATA.est.verano_hora.length)return;
  const svg=document.getElementById('veranohora');const box=svg.parentElement.getBoundingClientRect();
  const W=box.width;if(W<40)return;const H=Math.max(220,Math.min(320,W*0.3));const m={l:32,r:12,t:10,b:22};
  const d=DATA.est.verano_hora;const ys=d.map(p=>p[1]);
  let ymin=Math.min(...ys),ymax=Math.max(...ys);const pad=(ymax-ymin)*0.06;ymin-=pad;ymax+=pad;
  const SX=i=>m.l+i/(d.length-1)*(W-m.l-m.r),SY=v=>H-m.b-(v-ymin)/(ymax-ymin)*(H-m.t-m.b);
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML='';
  niceTicks(ymin,ymax,4).forEach(t=>{svg.appendChild(el('line',{class:'gridline',x1:m.l,y1:SY(t),x2:W-m.r,y2:SY(t)}));
    const tx=el('text',{class:'axis',x:m.l-5,y:SY(t)+3,'text-anchor':'end'});tx.textContent=t.toFixed(0);svg.appendChild(tx);});
  let lastM='';d.forEach((p,i)=>{const mo=p[0].slice(5,7);if(mo!==lastM){lastM=mo;
    const tx=el('text',{class:'axis',x:SX(i),y:H-7,'text-anchor':'middle'});tx.textContent=MESAB[+mo];svg.appendChild(tx);}});
  if(30>ymin&&30<ymax)svg.appendChild(el('line',{x1:m.l,y1:SY(30),x2:W-m.r,y2:SY(30),stroke:cssvar('--warm'),'stroke-width':1,'stroke-dasharray':'3 3'}));
  let ln='';d.forEach((p,i)=>ln+=(i?'L':'M')+SX(i)+' '+SY(p[1]));
  svg.appendChild(el('path',{d:ln,fill:'none',stroke:cssvar('--warm'),'stroke-width':0.8}));
  const tt=document.getElementById('ttvh');
  const ov=el('rect',{x:m.l,y:m.t,width:W-m.l-m.r,height:H-m.t-m.b,fill:'transparent'});
  ov.addEventListener('mousemove',ev=>{const rb=svg.getBoundingClientRect();const px=(ev.clientX-rb.left)/rb.width*W;
    const i=Math.max(0,Math.min(d.length-1,Math.round((px-m.l)/(W-m.l-m.r)*(d.length-1))));const p=d[i];
    tt.style.left=(SX(i)/W*rb.width)+'px';tt.style.top=(SY(p[1])/H*rb.height)+'px';tt.style.opacity=1;
    tt.textContent=`${p[0].slice(8,10)}-${MESAB[+p[0].slice(5,7)]} ${p[0].slice(11)}h: ${p[1]}\u00b0`;});
  ov.addEventListener('mouseleave',()=>tt.style.opacity=0);svg.appendChild(ov);
  document.getElementById('vhtitle').textContent=`Temperatura horaria del verano de ${DATA.est.verano_anio} \u00b7 l\u00ednea naranja = 30 \u00b0C`;}

function renderAll(){
  drawStripes();drawChart(CUR||DATA.vars[0]);drawHeat();drawHeatSel();drawDist();
  drawEstMeta();drawDiaTipico();drawVeranos();drawNtrop();drawVeranoHora();
  drawSiglo();drawBilbao();drawSeaAnim();drawSST();drawMapActive();drawCmp();
}
let rt;
function showView(v){
  document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='v-'+v));
  document.querySelectorAll('#nav .navtab').forEach(b=>b.setAttribute('aria-selected',b.dataset.v===v));
  renderAll();
}
function init(){
  CUR=DATA.vars[0];
  buildTabs();buildRanking();buildDistTabs();
  if(DATA.gridyears){const towns=DATA.map.towns;
    cmpA=Math.max(0,towns.findIndex(t=>t[0]==='Laredo'));
    cmpB=Math.max(0,towns.findIndex(t=>t[0]==='Potes'));
    buildCmpTabs();
    document.getElementById('myplay').onclick=playMapYear;
    document.getElementById('myslider').max=DATA.gridyears.years.length-1;
    document.getElementById('myslider').oninput=e=>{
      if(myTimer){clearInterval(myTimer);myTimer=null;document.getElementById('myplay').textContent='\u25b6 Reproducir';}
      myIdx=+e.target.value;drawMapYear();};
  }
  document.getElementById('mmYear').onclick=()=>setMapMode('year');
  document.getElementById('mmTrend').onclick=()=>setMapMode('trend');
  document.getElementById('playbtn').onclick=playDist;
  document.getElementById('seaplay').onclick=playSea;
  document.querySelectorAll('#nav .navtab').forEach(b=>b.onclick=()=>showView(b.dataset.v));
  setMapMode('year');
  renderAll();
  const ro=new ResizeObserver(()=>{clearTimeout(rt);rt=setTimeout(renderAll,120);});
  ro.observe(document.body);
}
if(document.readyState!=='loading')init();
else window.addEventListener('DOMContentLoaded',init);

